builder.Services.AddDbContext<AppDbContext>(options =>
{
    options.UseSqlServer(conn);
    options.UseQueryTrackingBehavior(QueryTrackingBehavior.NoTracking);
});

// Read — default no tracking
var orders = await db.Orders
    .Where(o => o.CustomerId == customerId)
    .ToListAsync(ct);

// Write — opt in to tracking
var order = await db.Orders.AsTracking().FirstAsync(o => o.Id == id, ct);
order.Status = OrderStatus.Shipped;
await db.SaveChangesAsync(ct);

// Pattern A: load tracked, modify (simple updates)
var order = await db.Orders.AsTracking().FirstAsync(o => o.Id == id, ct);
order.Notes = req.Notes;
await db.SaveChangesAsync(ct);

// Pattern B: Attach + mark modified (when client sends full entity)
var incoming = new Order { Id = id, Notes = req.Notes, Total = 99.00m };
db.Orders.Attach(incoming);
db.Entry(incoming).Property(o => o.Notes).IsModified = true;
await db.SaveChangesAsync(ct);

// Tag queries to correlate SQL logs with endpoints
var orders = await db.Orders
    .AsNoTracking()
    .TagWith("GET /api/orders list")
    .ToListAsync(ct);

